#define DRJIT_OURS_VK_MAKE_API_VERSION(variant, major, minor, patch) ((((uint32_t) (variant)) << 29U) | (((uint32_t) (major)) << 22U) |               (((uint32_t) (minor)) << 12U) | ((uint32_t) (patch)))
