static_assert(check::same_shape<decltype(ours::spv_text_t::length), decltype(::spv_text_t::length)>(), "spv_text_t::length: type");
static_assert(sizeof(ours::spv_position_t) == sizeof(::spv_position_t), "sizeof(spv_position_t)");
static_assert(alignof(ours::spv_position_t) == alignof(::spv_position_t), "alignof(spv_position_t)");
static_assert(offsetof(ours::spv_position_t, line) == offsetof(::spv_position_t, line), "spv_position_t::line: offset");
static_assert(check::same_shape<decltype(ours::spv_position_t::line), decltype(::spv_position_t::line)>(), "spv_position_t::line: type");
static_assert(offsetof(ours::spv_position_t, column) == offsetof(::spv_position_t, column), "spv_position_t::column: offset");
static_assert(check::same_shape<decltype(ours::spv_position_t::column), decltype(::spv_position_t::column)>(), "spv_position_t::column: type");
static_assert(offsetof(ours::spv_position_t, index) == offsetof(::spv_position_t, index), "spv_position_t::index: offset");
static_assert(check::same_shape<decltype(ours::spv_position_t::index), decltype(::spv_position_t::index)>(), "spv_position_t::index: type");
