static_assert(check::same_shape<decltype(ours::spv_diagnostic_t::position), decltype(::spv_diagnostic_t::position)>(), "spv_diagnostic_t::position: type");
static_assert(offsetof(ours::spv_diagnostic_t, error) == offsetof(::spv_diagnostic_t, error), "spv_diagnostic_t::error: offset");
static_assert(check::same_shape<decltype(ours::spv_diagnostic_t::error), decltype(::spv_diagnostic_t::error)>(), "spv_diagnostic_t::error: type");
