static_assert(check::same_shape<decltype(ours::spv_diagnostic_t::isTextSource), decltype(::spv_diagnostic_t::isTextSource)>(), "spv_diagnostic_t::isTextSource: type");
static_assert(check::same_shape<ours::PFN_spvContextCreate, decltype(&::spvContextCreate)>(), "PFN_spvContextCreate");
