#endif // DRJIT_CHECK_SPIRV_TOOLS

static int checks_run = 0, checks_failed = 0;

#define CHECK(cond, msg)                                                       \
    do {                                                                       \
        checks_run++;                                                          \
        if (!(cond)) {                                                         \
            fprintf(stderr, "Check failed: %s\n", msg);                        \
            checks_failed++;                                                   \
        }                                                                      \
    } while (0)

#endif // defined(VK_API_VERSION_1_3)

int main() {
#if !defined(VK_API_VERSION_1_3)
    printf("test_vulkan_layout: skipped (the official Vulkan headers are too "
           "old, version 1.3 or newer is required).\n");
    return 0;
#else
    {
        ours::VkAccelerationStructureInstanceKHR a; ::VkAccelerationStructureInstanceKHR b;
        memset((void *) &a, 0, sizeof(a));
        memset((void *) &b, 0, sizeof(b));
        a.instanceCustomIndex = b.instanceCustomIndex = 0x3c96e1;
        a.mask = b.mask = 0xdc;
        a.instanceShaderBindingTableRecordOffset = b.instanceShaderBindingTableRecordOffset = 0x68f25b;
        a.flags = b.flags = 0x4b;
        CHECK(memcmp((const void *) &a, (const void *) &b, sizeof(a)) == 0, "VkAccelerationStructureInstanceKHR: bit fields");
    }
    CHECK(strcmp(DRJIT_OURS_VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME, VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME) == 0, "VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME");
    CHECK(strcmp(DRJIT_OURS_VK_KHR_RAY_QUERY_EXTENSION_NAME, VK_KHR_RAY_QUERY_EXTENSION_NAME) == 0, "VK_KHR_RAY_QUERY_EXTENSION_NAME");
    CHECK(strcmp(DRJIT_OURS_VK_KHR_DEFERRED_HOST_OPERATIONS_EXTENSION_NAME, VK_KHR_DEFERRED_HOST_OPERATIONS_EXTENSION_NAME) == 0, "VK_KHR_DEFERRED_HOST_OPERATIONS_EXTENSION_NAME");
    CHECK(strcmp(DRJIT_OURS_VK_EXT_SHADER_ATOMIC_FLOAT_EXTENSION_NAME, VK_EXT_SHADER_ATOMIC_FLOAT_EXTENSION_NAME) == 0, "VK_EXT_SHADER_ATOMIC_FLOAT_EXTENSION_NAME");
    CHECK(strcmp(DRJIT_OURS_VK_KHR_PORTABILITY_ENUMERATION_EXTENSION_NAME, VK_KHR_PORTABILITY_ENUMERATION_EXTENSION_NAME) == 0, "VK_KHR_PORTABILITY_ENUMERATION_EXTENSION_NAME");

#if defined(DRJIT_CHECK_SPIRV_TOOLS)
    const int n_static = 2027 + 76;
    const char *what = "Vulkan and SPIRV-Tools";
#else
    const int n_static = 2027;
    const char *what = "Vulkan";
#endif

    if (checks_failed) {
        fprintf(stderr, "test_vulkan_layout: %i/%i runtime checks failed!\n",
                checks_failed, checks_run);
        return 1;
    }

    printf("test_vulkan_layout: %s declarations match the official headers "
           "(%i static and %i runtime checks passed).\n", what, n_static,
           checks_run);
    return 0;
#endif
}
